import {
  MjmlButton,
  MjmlColumn,
  MjmlDivider,
  MjmlImage,
  MjmlSection,
  MjmlSpacer,
  MjmlText,
  Mjml,
  MjmlBody,
  MjmlFont,
  MjmlHead,
  MjmlPreview,
  MjmlStyle,
  MjmlWrapper,
} from "@faire/mjml-react";
import { Fragment } from "react";

import type { EmailTheme } from "@/components/email/email-theme";
import { emailAsset } from "@/components/email/email-assets";
import { defaultTheme } from "@/components/email/theme-default";

export type ShoppingCartVariant =
  | "basic"
  | "basic-alt"
  | "with-details"
  | "details-alt"
  | "full-details"
  | "full-details-alt"
  | "example-with-cta";

export interface ShoppingCartItem {
  colors?: string[];
  description?: string;
  editHref?: string;
  imageUrl?: string;
  name: string;
  price: string;
  quantity: number;
  size?: string;
}

const fontFamily =
  'Inter, ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif';

const shoppingCartResponsiveStyles = "";

const defaultItems: ShoppingCartItem[] = [
  {
    colors: ["#030712", "#fffffe", "#E5E7EB"],
    description:
      "Crafted from a soft bamboo-linen blend, this shirt combines breathability, comfort...",
    editHref: "https://example.com/cart/edit",
    imageUrl: emailAsset(`shopping-cart/shopping-cart-1.jpg`),
    name: "Bio Bamboo Indigo Shirt",
    price: "$9.99",
    quantity: 2,
    size: "Large",
  },
  {
    colors: ["#030712", "#E5E7EB"],
    description:
      "Crafted from a soft bamboo-linen blend, this shirt combines breathability, comfort...",
    editHref: "https://example.com/cart/edit",
    imageUrl: emailAsset(`shopping-cart/shopping-cart-2.jpg`),
    name: "Bio Bamboo Earth Shirt",
    price: "$9.99",
    quantity: 2,
    size: "Medium",
  },
  {
    colors: ["#E5E7EB", "#fffffe"],
    description:
      "Crafted from a soft bamboo-linen blend, this shirt combines breathability, comfort...",
    editHref: "https://example.com/cart/edit",
    imageUrl: emailAsset(`shopping-cart/shopping-cart-3.jpg`),
    name: "Bio Bamboo Natural Shirt",
    price: "$9.99",
    quantity: 1,
    size: "Small",
  },
  {
    colors: ["#E5E7EB", "#030712"],
    description:
      "Crafted from a soft bamboo-linen blend, this shirt combines breathability, comfort...",
    editHref: "https://example.com/cart/edit",
    imageUrl: emailAsset(`shopping-cart/shopping-cart-4.jpg`),
    name: "Bio Bamboo Basic Shirt",
    price: "$9.99",
    quantity: 3,
    size: "Extra Large",
  },
];

const Copy = ({ children }: { children?: string }) =>
  children ? (
    <MjmlText
      color="#4b5563"
      fontFamily={fontFamily}
      fontSize="16px"
      fontWeight="300"
      lineHeight="24px"
      padding="0"
    >
      {children}
    </MjmlText>
  ) : null;

const EditButton = ({ href }: { href: string }) => (
  <MjmlButton
    align="left"
    backgroundColor="transparent"
    color="#4f46e5"
    fontFamily={fontFamily}
    fontSize="16px"
    fontWeight="500"
    href={href}
    innerPadding="4px 0"
    lineHeight="16px"
    padding="0"
  >
    ✎ Edit
  </MjmlButton>
);

const RowContent = ({
  item,
  variant,
}: {
  item: ShoppingCartItem;
  variant: ShoppingCartVariant;
}) => {
  const isAlt = variant.endsWith("-alt") || variant === "basic-alt";
  const hasOptions = !["basic", "basic-alt"].includes(variant);
  const hasDescription = [
    "full-details",
    "full-details-alt",
    "example-with-cta",
  ].includes(variant);
  const showQuantityOption = variant !== "full-details-alt";
  let details = `Indigo · ${item.size ?? "Large"}`;
  if (hasOptions) {
    const quantity = showQuantityOption ? ` · Quantity: ${item.quantity}` : "";
    details = `Colors: ${(item.colors ?? ["#030712", "#fffffe", "#E5E7EB"]).length} options · Size: ${item.size ?? "Large"}${quantity}`;
  } else if (variant === "basic") {
    details = `${details} · Quantity: ${item.quantity}`;
  }
  return (
    <>
      <MjmlText
        color="#030712"
        fontFamily={fontFamily}
        fontSize="20px"
        fontWeight="600"
        lineHeight="28px"
        padding="0"
      >
        {item.name} · {item.price}
      </MjmlText>
      <MjmlSpacer height="24px" />
      {hasDescription ? (
        <>
          <Copy>{item.description}</Copy>
          <MjmlDivider
            borderColor="#d1d5db"
            borderWidth="1px"
            padding="24px 0 8px"
          />
        </>
      ) : null}
      <Copy>{details}</Copy>
      {hasDescription ? (
        <MjmlDivider
          borderColor="#d1d5db"
          borderWidth="1px"
          padding="8px 0 0"
        />
      ) : null}
      <MjmlSpacer height={hasDescription && !isAlt ? "24px" : "34px"} />
      {isAlt ? (
        <>
          <MjmlText
            color="#4b5563"
            fontFamily={fontFamily}
            fontSize="14px"
            fontWeight="500"
            lineHeight="20px"
            padding="0"
          >
            Qty: {item.quantity}
          </MjmlText>
          <MjmlSpacer height="8px" />
          <EditButton href={item.editHref ?? "https://example.com/cart/edit"} />
        </>
      ) : (
        <EditButton href={item.editHref ?? "https://example.com/cart/edit"} />
      )}
    </>
  );
};

const CartRow = ({
  item,
  variant,
}: {
  item: ShoppingCartItem;
  variant: ShoppingCartVariant;
}) => (
  <MjmlSection backgroundColor="#fffffe" padding="0 24px">
    <MjmlColumn padding="0 24px 0 0" verticalAlign="top" width="168px">
      <MjmlImage
        alt={item.name}
        borderRadius="8px"
        padding="0"
        src={item.imageUrl}
        width="144px"
      />
    </MjmlColumn>
    <MjmlColumn padding="0" verticalAlign="top">
      <RowContent item={item} variant={variant} />
    </MjmlColumn>
  </MjmlSection>
);

const ShoppingCartSection = ({
  items,
  variant = "basic",
}: {
  items?: ShoppingCartItem[];
  variant?: ShoppingCartVariant;
}) => {
  const list = items ?? defaultItems;
  const visible =
    variant === "example-with-cta"
      ? list.slice(0, 4).map((item) => ({
          ...item,
          colors: item.colors?.slice(0, 2),
        }))
      : list.slice(0, 1);
  const rowVariant =
    variant === "example-with-cta" ? "example-with-cta" : variant;
  return (
    <>
      <MjmlSection backgroundColor="#fffffe" padding="44px 0 0">
        <MjmlColumn padding="0">
          <MjmlSpacer height="1px" />
        </MjmlColumn>
      </MjmlSection>
      {visible.map((item, index) => (
        <Fragment key={`${item.name}-${index}`}>
          <CartRow item={item} variant={rowVariant} />
          {index < visible.length - 1 ? (
            <MjmlSection backgroundColor="#fffffe" padding="0">
              <MjmlColumn padding="0">
                <MjmlSpacer height="44px" />
              </MjmlColumn>
            </MjmlSection>
          ) : null}
        </Fragment>
      ))}
      {variant === "example-with-cta" ? (
        <MjmlSection backgroundColor="#fffffe" padding="64px 24px 0">
          <MjmlColumn padding="0">
            <MjmlButton
              backgroundColor="#4f46e5"
              borderRadius="8px"
              color="#f8fafc"
              fontFamily={fontFamily}
              fontSize="16px"
              fontWeight="500"
              href="https://example.com/checkout"
              innerPadding="14px 22px"
              lineHeight="16px"
              padding="0"
            >
              Checkout now
            </MjmlButton>
          </MjmlColumn>
        </MjmlSection>
      ) : null}
      <MjmlSection backgroundColor="#fffffe" padding="0">
        <MjmlColumn padding="0">
          <MjmlSpacer height="44px" />
        </MjmlColumn>
      </MjmlSection>
    </>
  );
};

interface ShoppingCart_ShoppingCartRowItemsProps {
  items?: ShoppingCartItem[];
  theme?: EmailTheme;
  variant?: ShoppingCartVariant;
}

const ShoppingCart_ShoppingCartRowItemsSection = ({
  items,
  variant = "basic",
}: Omit<ShoppingCart_ShoppingCartRowItemsProps, "theme">) => (
  <ShoppingCartSection items={items} variant={variant} />
);

const ShoppingCart_ShoppingCartRowItems = ({
  theme = defaultTheme,
  ...props
}: ShoppingCart_ShoppingCartRowItemsProps) => (
  <Mjml>
    <MjmlHead>
      <MjmlPreview>Shopping cart</MjmlPreview>
      <MjmlFont href="https://rsms.me/inter/inter.css" name="Inter" />
      <MjmlStyle>{shoppingCartResponsiveStyles}</MjmlStyle>
    </MjmlHead>
    <MjmlBody backgroundColor="#f1f5f9" width={theme.containerWidth}>
      <MjmlWrapper padding="0">
        <ShoppingCart_ShoppingCartRowItemsSection {...props} />
      </MjmlWrapper>
    </MjmlBody>
  </Mjml>
);

ShoppingCart_ShoppingCartRowItems.PreviewProps = {
  theme: defaultTheme,
  variant: "basic",
} satisfies ShoppingCart_ShoppingCartRowItemsProps;

const __ShoppingCart = ShoppingCart_ShoppingCartRowItems;

export interface ShoppingCartProps extends Omit<
  Parameters<typeof __ShoppingCart>[0],
  "theme"
> {
  theme?: Parameters<typeof __ShoppingCart>[0]["theme"];
}

export const ShoppingCart = (props: ShoppingCartProps) => (
  <__ShoppingCart {...props} />
);

ShoppingCart.PreviewProps = {} satisfies ShoppingCartProps;

const ASSET_ORIGIN = "https://www.emailcn.run";
const ICONS8_ORIGIN = "https://img.icons8.com";
const UNSPLASH_ORIGIN = "https://images.unsplash.com";

const portraitIds = [
  "photo-1500648767791-00dcc994a43e",
  "photo-1507003211169-0a1dd7228f2d",
  "photo-1494790108377-be9c29b29330",
  "photo-1438761681033-6461ffad8d80",
  "photo-1534528741775-53994a69daeb",
  "photo-1506794778202-cad84cf45f1c",
] as const;

const productIds = [
  "photo-1521572163474-6864f9cf17ab",
  "photo-1503341504253-dff4815485f1",
  "photo-1576566588028-4147f3842f27",
  "photo-1562157873-818bc0726f68",
] as const;

const socialIconSlugs = {
  discord: "discord-logo",
  facebook: "facebook-new",
  github: "github",
  instagram: "instagram-new",
  linkedin: "linkedin",
  slack: "slack-new",
  x: "twitterx--v1",
  youtube: "youtube-play",
} as const;

const brandIconSlugs = [
  [/(?:btc|bitcoin)/i, "bitcoin--v1"],
  [/(?:eth|ethereum)/i, "ethereum"],
  [/visa/i, "visa"],
  [/mastercard/i, "mastercard-logo"],
  [/apple-pay/i, "apple-pay"],
  [/google-pay/i, "google-pay"],
  [/klarna/i, "klarna"],
  [/stripe/i, "stripe"],
  [/fedex/i, "fedex"],
  [/north-face/i, "the-north-face"],
] as const;

const hashString = (value: string) => {
  let hash = 7;

  for (const character of value) {
    hash = (hash * 31 + (character.codePointAt(0) ?? 0)) % 2_147_483_647;
  }

  return hash;
};

const getDimensions = (path: string) => {
  if (/teams\/member-\d+-lg/i.test(path)) {
    return [800, 560] as const;
  }
  if (/teams\/member-\d+/i.test(path)) {
    return [600, 600] as const;
  }
  if (/(?:avatar|user|headshot)/i.test(path)) {
    return [160, 160] as const;
  }
  if (/(?:logo|insignia)/i.test(path)) {
    return [320, 96] as const;
  }
  if (/(?:badge-app|badge-google)/i.test(path)) {
    return [260, 80] as const;
  }
  if (/(?:icon|btc|eth)/i.test(path)) {
    return [64, 64] as const;
  }
  if (/(?:portrait|member|team)/i.test(path)) {
    return [600, 800] as const;
  }
  if (/(?:square|product|shopping-cart)/i.test(path)) {
    return [700, 700] as const;
  }
  if (/(?:hero|footer|background|bg-|overlay|full-width)/i.test(path)) {
    return [1200, 700] as const;
  }
  if (/(?:strip|landscape|bento|category-preview)/i.test(path)) {
    return [800, 520] as const;
  }

  return [800, 600] as const;
};

const getSeed = (path: string) =>
  `emailcn-${path
    .replace(/\.[^.]+$/, "")
    .replaceAll(/[^a-z0-9]+/gi, "-")
    .replaceAll(/^-|-$/g, "")
    .toLowerCase()}`;

const getIndexedAsset = (path: string, assets: readonly string[]) => {
  const explicitIndex = path.match(
    /(?:member|avatar|product-list|shopping-cart)-(\d+)/i
  )?.[1];
  const index = explicitIndex
    ? Number.parseInt(explicitIndex, 10) - 1
    : hashString(path);

  return assets[((index % assets.length) + assets.length) % assets.length];
};

const getUnsplashAsset = (id: string, width: number, height: number) =>
  `${UNSPLASH_ORIGIN}/${id}?auto=format&fit=crop&w=${width}&h=${height}&q=80`;

const getIcons8Asset = (
  slug: string,
  {
    color,
    style = "ios-filled",
  }: {
    color?: string;
    style?: "color" | "ios" | "ios-filled";
  } = {}
) =>
  color
    ? `${ICONS8_ORIGIN}/${style}/50/${color}/${slug}.png`
    : `${ICONS8_ORIGIN}/${style}/50/${slug}.png`;

const getStoreBadgeAsset = (path: string) => {
  if (/badge-app-store/i.test(path)) {
    return "https://developer.apple.com/assets/elements/badges/download-on-the-app-store.svg";
  }
  if (/badge-google-play/i.test(path)) {
    return "https://play.google.com/intl/en_us/badges/static/images/badges/en_badge_web_generic.png";
  }
};

const getSocialIconAsset = (path: string) => {
  const isLight = /(?:-light|check-white)/i.test(path);
  const foreground = isLight ? "FFFFFF" : "111827";

  for (const [name, slug] of Object.entries(socialIconSlugs)) {
    if (new RegExp(`(?:^|[-/])${name}(?:[-.]|$)`, "i").test(path)) {
      return getIcons8Asset(slug, { color: foreground });
    }
  }
};

const getUtilityIconAsset = (path: string) => {
  const isLight = /(?:-light|check-white)/i.test(path);
  const foreground = isLight ? "FFFFFF" : "111827";

  if (/star-half/i.test(path)) {
    return getIcons8Asset("star-half-empty", { color: "374151" });
  }
  if (/star-solid/i.test(path)) {
    return getIcons8Asset("star--v1", { color: "374151" });
  }
  if (/edit/i.test(path)) {
    return getIcons8Asset("edit--v1", {
      color: "4F46E5",
      style: "ios",
    });
  }
  if (/arrow-right/i.test(path)) {
    return getIcons8Asset("long-arrow-right--v1", {
      color: "4F46E5",
      style: "ios",
    });
  }
  if (/chevron-right/i.test(path)) {
    return getIcons8Asset("chevron-right", {
      color: "4F46E5",
      style: "ios",
    });
  }
  if (/check/i.test(path)) {
    return getIcons8Asset("checkmark--v1", { color: foreground });
  }
};

const getBrandIconAsset = (path: string) => {
  const match = brandIconSlugs.find(([pattern]) => pattern.test(path));

  return match
    ? getIcons8Asset(match[1], {
        style: "color",
      })
    : undefined;
};

const getWordmarkAsset = (path: string) => {
  const isLight = /light/i.test(path);
  const background = isLight ? "030712" : "FFFFFF";
  const foreground = isLight ? "FFFFFF" : "111827";

  return `https://placehold.co/320x96/${background}/${foreground}.png?text=EMAILCN`;
};

const getIconAsset = (path: string) =>
  getStoreBadgeAsset(path) ??
  getSocialIconAsset(path) ??
  getUtilityIconAsset(path) ??
  getBrandIconAsset(path);

export const emailAsset = (path: string) => {
  const normalizedPath = path.replace(/^\/+/, "");

  if (
    normalizedPath === "bento-grids/trend.png" ||
    normalizedPath === "bento-grids/trend-sm.png"
  ) {
    return `${ASSET_ORIGIN}/email-assets/${normalizedPath}`;
  }

  const iconAsset = getIconAsset(normalizedPath);
  if (iconAsset) {
    return iconAsset;
  }

  const seed = getSeed(normalizedPath);
  const [width, height] = getDimensions(normalizedPath);

  if (/teams\/hero/i.test(normalizedPath)) {
    return getUnsplashAsset("photo-1521737711867-e3b97375f902", width, height);
  }

  if (/(?:avatar|user|headshot|member|team)/i.test(normalizedPath)) {
    return getUnsplashAsset(
      getIndexedAsset(normalizedPath, portraitIds),
      width,
      height
    );
  }

  if (/products\/shoe/i.test(normalizedPath)) {
    return getUnsplashAsset("photo-1542291026-7eec264c27ff", width, height);
  }

  if (/products\/phone/i.test(normalizedPath)) {
    return getUnsplashAsset("photo-1511707171634-5f897ff02aa9", width, height);
  }

  if (
    /(?:product-detail|product-lists|products\/product|shopping-cart)/i.test(
      normalizedPath
    )
  ) {
    return getUnsplashAsset(
      getIndexedAsset(normalizedPath, productIds),
      width,
      height
    );
  }

  if (/(?:trend|chart)/i.test(normalizedPath)) {
    return `${ASSET_ORIGIN}/email-assets/bento-grids/trend.png`;
  }

  if (/(?:emailcn|maizzle|logo|insignia)/i.test(normalizedPath)) {
    return getWordmarkAsset(normalizedPath);
  }

  return `https://picsum.photos/seed/${encodeURIComponent(
    seed
  )}/${width}/${height}.jpg`;
};
